import type { Block } from "./types";
import { getBlockComponent } from "./registry";

/**
 * Renders enabled schema-bound blocks. Unknown types → ignored.
 * Pass `isOwner` from the host (⛔ no draftMode inside the kit).
 */
export default function BlockZone({
  blocks,
  isOwner = false,
}: {
  blocks?: Block[] | null;
  isOwner?: boolean;
}) {
  if (!Array.isArray(blocks) || blocks.length === 0) return null;
  const rendered = blocks
    .filter((b) => b.enabled)
    .map((b, i) => {
      const Component = getBlockComponent(b.type);
      if (!Component) return null;
      const key = b.id ? b.id : `blk-${i}`;
      return <Component key={key} data={b.data} isOwner={isOwner} />;
    });
  if (!rendered.some((r) => r !== null)) return null;
  return <>{rendered}</>;
}

import type { ComponentType } from "react";
import type {
  CardsData,
  CTAData,
  GalleryData,
  RichSectionData,
  TestimonialsData,
} from "./types";

// Full kit smoke: install BlockZone + all 5 canonical renderers together.
// Zone-alone without renderers is unsupported — paths assume sibling tree after
// `npx shadcn add @guaso/block-zone @guaso/rich-section @guaso/cta @guaso/gallery @guaso/cards @guaso/testimonials`.
import RichSection from "../rich-section/rich-section";
import Gallery from "../gallery/gallery";
import Cards from "../cards/cards";
import Testimonials from "../testimonials/testimonials";
import CTABlock from "../cta/cta";

export type BlockRenderer = ComponentType<{ data: unknown; isOwner?: boolean }>;

type RegistryEntry = {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  Component: ComponentType<{ data: any; isOwner?: boolean }>;
};

const REGISTRY_RAW: Record<string, RegistryEntry> = {
  RichSection: {
    Component: RichSection as ComponentType<{ data: RichSectionData }>,
  },
  Gallery: {
    Component: Gallery as ComponentType<{ data: GalleryData }>,
  },
  Cards: {
    Component: Cards as ComponentType<{ data: CardsData }>,
  },
  Testimonials: {
    Component: Testimonials as ComponentType<{ data: TestimonialsData }>,
  },
  CTA: {
    Component: CTABlock as ComponentType<{ data: CTAData }>,
  },
};

/** Lookup by block `type` (PascalCase). Unknown → undefined (forward-compat). */
export function getBlockComponent(type: string): BlockRenderer | undefined {
  const entry = REGISTRY_RAW[type];
  if (!entry) return undefined;
  return entry.Component as ComponentType<{ data: unknown; isOwner?: boolean }>;
}

export const SUPPORTED_BLOCK_TYPES = Object.keys(REGISTRY_RAW) as Array<
  "RichSection" | "Gallery" | "Cards" | "Testimonials" | "CTA"
>;

// UI structural types for BlockZone + skins. Backend validates lengths.
// Block + safeHref stay local. Zone-only install must typecheck without
// the content npm package (#3579).

export type Block = {
  id: string;
  type: string;
  enabled: boolean;
  data: Record<string, unknown>;
};

export type RichSectionData = {
  title?: string;
  body?: string;
  cta_label?: string;
  cta_url?: string;
  align?: "left" | "center";
  image_url?: string;
};

export type CTAData = {
  headline?: string;
  subtext?: string;
  button_label?: string;
  button_url?: string;
};

export type GalleryImage = {
  url: string; // runtime/upload; not in repeatable schema (alt/caption only) — same as templates
  alt?: string;
  caption?: string;
};

export type GalleryData = {
  title?: string;
  images?: GalleryImage[];
};

export type CardItem = {
  heading?: string;
  text?: string;
  link_label?: string;
  link_url?: string;
};

export type CardsData = {
  title?: string;
  subtitle?: string;
  cards?: CardItem[];
};

export type TestimonialItem = {
  author?: string;
  role?: string;
  quote?: string;
};

export type TestimonialsData = {
  title?: string;
  items?: TestimonialItem[];
};

/**
 * Safe href for block CTAs / links.
 * Allows http(s)/mailto/tel and relative paths starting with `/`.
 * Rejects javascript:, data:, protocol-relative, and empty.
 */
export function safeHref(url?: string): string | undefined {
  if (!url || typeof url !== "string") return undefined;
  const trimmed = url.trim();
  if (!trimmed) return undefined;

  if (
    trimmed.startsWith("/") &&
    !trimmed.startsWith("//") &&
    !trimmed.startsWith("/\\")
  ) {
    return trimmed;
  }

  const lower = trimmed.toLowerCase();
  if (
    lower.startsWith("http://") ||
    lower.startsWith("https://") ||
    lower.startsWith("mailto:") ||
    lower.startsWith("tel:")
  ) {
    return trimmed;
  }

  return undefined;
}
